values (
  'cp-practice-binary-search-tree-112', 'dt-practice-binary-search-tree', null,
  $px$Insert into BST$px$, $px$insert-into-bst$px$, $px$Medium$px$,
  $px$Insert a new value into a Binary Search Tree, following the usual BST rule (smaller values go left, larger go right), and print the resulting tree.

The result is printed in canonical level-order form: a breadth-first walk emitting each value and `null` for a real node's missing child, with trailing `null` tokens removed.

**Input Format**

The first line contains an integer `M`.
The second line contains `M` space-separated tokens (integers or `null`) — the BST in level order.
The third line contains the integer `X` to insert.

**Output Format**

Print the canonical level-order serialization of the BST after the insertion.$px$,
  $px$[{"input":"3\n8 3 10\n6","output":"8 3 10 null 6","explanation":"6 < 8 and 6 > 3, so it becomes the right child of 3."}]$px$::jsonb,
  $px$["1 <= number of nodes <= 5000","The value X does not already exist.","-1000000000 <= value, X <= 1000000000"]$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        // TODO: read the input, compute the answer, and print it\n    }\n}\n","python":"import sys\n\ndata = sys.stdin.read()\n# TODO: parse the input above and print the answer\n","c":"#include <stdio.h>\n\nint main(void) {\n    // TODO: read input with scanf / fgets, compute, print with printf\n    return 0;\n}\n","cpp":"#include <iostream>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // TODO: read the input, compute the answer, and print it\n    return 0;\n}\n","javascript":"const data = require('fs').readFileSync(0, 'utf8');\n// TODO: parse the input above and print the answer\n"}$px$::jsonb,
  $px${"java":"import java.util.*;\nimport java.io.*;\npublic class Main {\n    static long[] V; static int[] L, R; static int cnt;\n    static int ins(int x, long key) {\n        if (x == -1) { V[cnt] = key; L[cnt] = -1; R[cnt] = -1; return cnt++; }\n        if (key < V[x]) L[x] = ins(L[x], key); else R[x] = ins(R[x], key);\n        return x;\n    }\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        String[] toks = br.readLine().trim().split(\"\\\\s+\");\n        long X = Long.parseLong(br.readLine().trim());\n        int sz = m + 2;\n        V = new long[sz]; L = new int[sz]; R = new int[sz];\n        V[0] = Long.parseLong(toks[0]); L[0] = -1; R[0] = -1; cnt = 1;\n        int[] q = new int[m + 1]; int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n        while (qh < qt && i < toks.length) {\n            int cur = q[qh++];\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Long.parseLong(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n            if (i < toks.length && !toks[i].equals(\"null\")) { V[cnt] = Long.parseLong(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n            i++;\n        }\n        int root = ins(0, X);\n        ArrayList<String> out = new ArrayList<>();\n        ArrayDeque<Integer> bq = new ArrayDeque<>();\n        bq.add(root);\n        while (!bq.isEmpty()) {\n            int x = bq.poll();\n            if (x == -1) { out.add(\"null\"); continue; }\n            out.add(String.valueOf(V[x]));\n            bq.add(L[x]); bq.add(R[x]);\n        }\n        while (!out.isEmpty() && out.get(out.size() - 1).equals(\"null\")) out.remove(out.size() - 1);\n        System.out.println(String.join(\" \", out));\n    }\n}\n","python":"import sys\nsys.setrecursionlimit(20000)\nlines = sys.stdin.read().split('\\n')\nm = int(lines[0])\ntoks = lines[1].split()\nX = int(lines[2].strip())\nV, L, R = [], [], []\nV.append(int(toks[0])); L.append(-1); R.append(-1)\nq = [0]; qh = 0; i = 1; cnt = 1\nwhile qh < len(q) and i < len(toks):\n    cur = q[qh]; qh += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); L[cur] = cnt; q.append(cnt); cnt += 1\n    i += 1\n    if i < len(toks) and toks[i] != 'null':\n        V.append(int(toks[i])); L.append(-1); R.append(-1); R[cur] = cnt; q.append(cnt); cnt += 1\n    i += 1\ndef ins(x, key):\n    if x == -1:\n        V.append(key); L.append(-1); R.append(-1)\n        return len(V) - 1\n    if key < V[x]:\n        L[x] = ins(L[x], key)\n    else:\n        R[x] = ins(R[x], key)\n    return x\nroot = ins(0, X)\nout = []\nqq = [root]; qh = 0\nwhile qh < len(qq):\n    x = qq[qh]; qh += 1\n    if x == -1:\n        out.append('null')\n    else:\n        out.append(str(V[x])); qq.append(L[x]); qq.append(R[x])\nwhile out and out[-1] == 'null':\n    out.pop()\nprint(' '.join(out))\n","c":"#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\nlong long *V;\nint *L, *R, cnt;\nint ins(int x, long long key) {\n    if (x == -1) { V[cnt] = key; L[cnt] = -1; R[cnt] = -1; return cnt++; }\n    if (key < V[x]) L[x] = ins(L[x], key); else R[x] = ins(R[x], key);\n    return x;\n}\nint main(void) {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n    char **toks = malloc(sizeof(char*) * m);\n    for (int i = 0; i < m; i++) { toks[i] = malloc(16); scanf(\"%15s\", toks[i]); }\n    long long X; scanf(\"%lld\", &X);\n    int sz = m + 2;\n    V = malloc(sizeof(long long) * sz); L = malloc(sizeof(int) * sz); R = malloc(sizeof(int) * sz);\n    V[0] = atoll(toks[0]); L[0] = -1; R[0] = -1; cnt = 1;\n    int *q = malloc(sizeof(int) * (m + 1)); int qh = 0, qt = 0; q[qt++] = 0; int i = 1;\n    while (qh < qt && i < m) {\n        int cur = q[qh++];\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; L[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n        if (i < m && strcmp(toks[i], \"null\") != 0) { V[cnt] = atoll(toks[i]); L[cnt] = -1; R[cnt] = -1; R[cur] = cnt; q[qt++] = cnt; cnt++; }\n        i++;\n    }\n    int root = ins(0, X);\n    char **out = malloc(sizeof(char*) * (2 * sz + 4));\n    int on = 0;\n    int *bq = malloc(sizeof(int) * (2 * sz + 4)); int bh = 0, bt = 0; bq[bt++] = root;\n    while (bh < bt) {\n        int x = bq[bh++];\n        if (x == -1) { out[on] = malloc(8); strcpy(out[on], \"null\"); on++; continue; }\n        out[on] = malloc(16); sprintf(out[on], \"%lld\", V[x]); on++;\n        bq[bt++] = L[x]; bq[bt++] = R[x];\n    }\n    while (on > 0 && strcmp(out[on - 1], \"null\") == 0) on--;\n    for (int k = 0; k < on; k++) printf(\"%s%s\", out[k], k + 1 < on ? \" \" : \"\");\n    printf(\"\\n\");\n    return 0;\n}\n","cpp":"#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <deque>\nusing namespace std;\nvector<long long> V; vector<int> L, R; int cnt;\nint ins(int x, long long key) {\n    if (x == -1) { V.push_back(key); L.push_back(-1); R.push_back(-1); return cnt++; }\n    if (key < V[x]) L[x] = ins(L[x], key); else R[x] = ins(R[x], key);\n    return x;\n}\nint main() {\n    ios::sync_with_stdio(false); cin.tie(nullptr);\n    int m; cin >> m; cin.ignore();\n    string line; getline(cin, line);\n    long long X; cin >> X;\n    vector<string> toks;\n    { istringstream iss(line); string tk; while (iss >> tk) toks.push_back(tk); }\n    V.push_back(stoll(toks[0])); L.push_back(-1); R.push_back(-1); cnt = 1;\n    vector<int> q{0}; size_t qh = 0, i = 1;\n    while (qh < q.size() && i < toks.size()) {\n        int cur = q[qh++];\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); L[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n        if (i < toks.size() && toks[i] != \"null\") { V.push_back(stoll(toks[i])); L.push_back(-1); R.push_back(-1); R[cur] = cnt; q.push_back(cnt); cnt++; }\n        i++;\n    }\n    int root = ins(0, X);\n    vector<string> out;\n    deque<int> bq; bq.push_back(root);\n    while (!bq.empty()) {\n        int x = bq.front(); bq.pop_front();\n        if (x == -1) { out.push_back(\"null\"); continue; }\n        out.push_back(to_string(V[x]));\n        bq.push_back(L[x]); bq.push_back(R[x]);\n    }\n    while (!out.empty() && out.back() == \"null\") out.pop_back();\n    for (size_t k = 0; k < out.size(); k++) { if (k) cout << ' '; cout << out[k]; }\n    cout << \"\\n\";\n    return 0;\n}\n","javascript":"const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\nconst m = Number(lines[0]);\nconst toks = lines[1].trim().split(/\\s+/);\nconst X = Number(lines[2].trim());\nconst V = [Number(toks[0])], L = [-1], R = [-1];\nlet cnt = 1;\nconst q = [0]; let qh = 0, i = 1;\nwhile (qh < q.length && i < toks.length) {\n    const cur = q[qh++];\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); L[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n    if (i < toks.length && toks[i] !== 'null') { V.push(Number(toks[i])); L.push(-1); R.push(-1); R[cur] = cnt; q.push(cnt); cnt++; }\n    i++;\n}\nfunction ins(x, key) {\n    if (x === -1) { V.push(key); L.push(-1); R.push(-1); return V.length - 1; }\n    if (key < V[x]) L[x] = ins(L[x], key); else R[x] = ins(R[x], key);\n    return x;\n}\nconst root = ins(0, X);\nconst out = [];\nconst bq = [root]; let bh = 0;\nwhile (bh < bq.length) {\n    const x = bq[bh++];\n    if (x === -1) { out.push('null'); continue; }\n    out.push(String(V[x]));\n    bq.push(L[x]); bq.push(R[x]);\n}\nwhile (out.length && out[out.length - 1] === 'null') out.pop();\nconsole.log(out.join(' '));\n"}$px$::jsonb,
